        node.log("Global variable 'mqttuser' = " + processedData.mqttuser);
    }

    if (processedData.mqttpass) {
        global.set("mqttpass", processedData.mqttpass);
        node.log("Global variable 'mqttpass' = •••••••••");
    }

    if (processedData.Send_bip !== undefined) {
        global.set("Send_bip", processedData.Send_bip);
        node.log("Global variable 'Send_bip' = " + processedData.Send_bip);
    }

    // Optional Home Assistant dashboard with the JK-BMS card
    global.set("create_dashboard", processedData.create_dashboard === true);
    node.log("Global variable 'create_dashboard' = " + (processedData.create_dashboard === true));

    // =========================================================
    // DASHBOARD LANGUAGE
    // =========================================================
    function sanitizeDashboardLanguage(v) {
        const s = String(v || "").trim().toLowerCase();
        if (s.startsWith("de")) return "de";
        if (s.startsWith("fr")) return "fr";
        return "en";
    }

    // Language tables shipped with the add-on (see /etc/node-red/*.json)
    function loadJson(file) {
        try {
            const fsMod = global.get("fs");
            return JSON.parse(fsMod.readFileSync(file, "utf8"));
        } catch (e) {
            node.warn("Could not load " + file + ": " + e.message);
            return null;
        }
    }

    // uiLanguage (de/en/fr): Home Assistant entity names and the built-in dashboard.
    const uiLanguage = sanitizeDashboardLanguage(processedData.dashboard_language || "en");

