    global.set("config.dashboardLanguage", uiLanguage);
    global.set("ui.language", uiLanguage);
    global.set("entity_labels", loadJson("/etc/node-red/entity-labels.json") || {});
    global.set("ui_text", loadJson("/etc/node-red/ui-text.json") || {});
    node.log("Global variable 'ui.language' = " + uiLanguage);

    // The Premium dashboards / licence check are not part of this fork.
