// Check whether the global variable already exists
const currentValue = global.get("Authorize_Modify_Settings");

// If the variable does not exist (undefined or null), initialise it to true
if (currentValue === undefined || currentValue === null) {
    global.set("Authorize_Modify_Settings", true);
    node.warn("✓ Authorize_Modify_Settings initialized to TRUE (first use)");

    // MQTT message with a flag to avoid a loop
    msg.payload = "true";
    msg.topic = "BMS_GLOBAL/authorize_modify_settings/state";
    msg.retain = true;
    msg.fromInit = true;  // flag that marks the initialisation

    return msg;
} else {
    // Variable already exists, do not overwrite it
    node.warn(`⊘ Authorize_Modify_Settings already exists (value: ${currentValue}) - no modification`);

    msg.payload = currentValue ? "true" : "false";
    msg.topic = "BMS_GLOBAL/authorize_modify_settings/state";
    msg.retain = true;
    msg.fromInit = true;  // FLAG

    return msg;
}

// Ignore messages coming from the initialisation
if (msg.fromInit) {
    return null;  // block the message to avoid a loop
}

// Convert string to boolean
