        }
    } else t1669.ack_crc_unavailable++;
    if (reason1669) {
        state1669.last_anomalies.push({
            ts:current1669,kind:kind1669,reason:reason1669,len:len1669
        });
        if (state1669.last_anomalies.length > 8)
