const crc = crc16(dataBuffer);

// Final buffer with CRC
const finalBuffer = Buffer.allocUnsafe(dataBuffer.length + 2);
dataBuffer.copy(finalBuffer);
finalBuffer.writeUInt16LE(crc, dataBuffer.length);

node.warn(`Writing register 0x1504 - RCVTime: ${rcvRaw} | RFVTime: ${rfvRaw}`);

msg.topic = "write_voltage_times";
msg.payload = finalBuffer;
return msg;

// Slave address from the global context
const slaveId = global.get("slaveAddress-Trame1") || 0x01; // default if not set
const functionCode = 0x03; // Function Code 3 : Read Holding Registers
const registerHigh = 0x15; // high address of 0x1504
const registerLow = 0x04;  // low address of 0x1504
const quantityHigh = 0x00; // register count high (0x0001 = 1 register)
const quantityLow = 0x01;  // register count low

// Calculer CRC16 Modbus
function crc16(buffer) {
    let crc = 0xFFFF;
    for (let i = 0; i < buffer.length; i++) {
        crc ^= buffer[i];
        for (let j = 0; j < 8; j++) {
            if (crc & 0x0001) {
                crc = (crc >> 1) ^ 0xA001;
            } else {
                crc = crc >> 1;
            }
        }
    }
    return crc;
}

// Build the buffer without CRC
const dataBuffer = Buffer.from([
    slaveId,
    functionCode,
    registerHigh,
    registerLow,
    quantityHigh,
    quantityLow
]);

// CRC
const crc = crc16(dataBuffer);

// Final buffer with CRC
