// Localised Home Assistant display name (option dashboard_language).
// Only the display name changes - unique_id / entity_id stay the same.
function entityLabel(rawKey) {
    const key = String(rawKey);
    const lang = String(global.get("ui.language") || "en");
    const table = global.get("entity_labels") || {};
    const pick = entry => (entry && (entry[lang] || entry.en)) || null;
    const lower = key.toLowerCase();
    const labels = table.labels || {};
    for (const k of Object.keys(labels)) {
        if (k.toLowerCase() === lower) {
            const v = pick(labels[k]);
            if (v) return v;
        }
    }
    for (const p of table.patterns || []) {
        const m = key.match(new RegExp(p.regex, "i"));
        const v = m && pick(p);
        if (v) return v.replace(/\{(\d+)\}/g, (_, i) => m[Number(i)] || "");
    }
    return key.replace(/_/g, " ");
