}
msg.bms_numero = parsed166;

// 0. Get the BMS address, convert to "master" when needed
let bmsAdresse = msg.bms_numero;
let slaveIdStr;

if (typeof bmsAdresse === "string" && bmsAdresse.toLowerCase() === "master") {
