function formatBoolean(value) {
    if (typeof value === "boolean") {
        return value ? "True" : "False";
    }
    if (typeof value === "string") {
        const lowerVal = value.toLowerCase();
        if (lowerVal === "true") return "True";
        if (lowerVal === "false") return "False";
    }
    return value;
}

function normalizeValue(value) {
    if (typeof value === "boolean") {
        return value ? "True" : "False";
    }
    if (typeof value === "number") {
        // avoids false changes 3.5 vs 3.500000
        return Number(value.toFixed(6));
    }
    if (typeof value === "string") {
        const lowerVal = value.toLowerCase();
        if (lowerVal === "true") return "True";
        if (lowerVal === "false") return "False";
        const asNum = Number(value);
        if (!Number.isNaN(asNum) && value.trim() !== "") {
            return Number(asNum.toFixed(6));
        }
        return value.trim();
    }
    return value;
}

function inferMeta(key) {
    // A few special cases kept on purpose
    const custom = {
        max_charge_current_A: { unit: "A", min: 0, max: 600, step: 1 },
        max_discharge_current_S: { unit: "A", min: 0, max: 600, step: 1 }, // historic key kept (entity id)
        max_balance_current_A: { unit: "A", min: 0, max: 10, step: 0.1 },
        total_battery_capacity_Ah: { unit: "Ah", min: 1, max: 2000, step: 1 },
        short_circuit_protection_delay_S: { unit: "s", min: 0, max: 5000, step: 1 },
        charge_overcurrent_protection_delay_S: { unit: "s", min: 0, max: 600, step: 1 },
        discharge_overcurrent_protection_delay_S: { unit: "s", min: 0, max: 600, step: 1 },
        charge_overcurrent_protection_recovery_time_S: { unit: "s", min: 0, max: 3600, step: 1 },
        discharge_overcurrent_protection_recovery_time_S: { unit: "s", min: 0, max: 3600, step: 1 },
        short_circuit_protection_recovery_time_S: { unit: "s", min: 0, max: 600, step: 1 },
        cell_count_N: { min: 1, max: 32, step: 1 },
        Device_address_N: { min: 0, max: 255, step: 1 }
    };

    if (custom[key]) return custom[key];

    if (key.endsWith("_V"))  return { unit: "V",  step: 0.001 };
    if (key.endsWith("_A"))  return { unit: "A",  step: 0.1 };
    if (key.endsWith("_Ah")) return { unit: "Ah", step: 1 };
    if (key.endsWith("_T"))  return { unit: "°C", step: 1 };
    if (key.endsWith("_S"))  return { unit: "s",  step: 1 };
    if (key.endsWith("_R"))  return { step: 0.001 };
    if (key.endsWith("_N"))  return { step: 1 };

    return {};
}

// Setup values that are shown read-only (no write handler exists for them).
const READ_ONLY_SETUP = {
    heating_switch_B: "binary", disable_temperature_sensors_B: "binary",
    port_rs485_mode_B: "binary", special_charger_B: "binary",
    emergency_button_trigger_B: "binary", dry_alarm_intermittent_B: "binary",
    discharge_ocp2_B: "binary", discharge_ocp3_B: "binary",
    precharge_time_D: "s", heating_start_temperature_T: "°C",
    heating_stop_temperature_T: "°C", smart_sleep_delay_H: "h",
    discharge_undertemperature_protection_T: "°C",
    discharge_undertemperature_protection_recovery_T: "°C"
};
function applyReadOnly(key, cfg) {
    const kind = READ_ONLY_SETUP[key];
    if (!kind) return null;
    delete cfg.command_topic;
    delete cfg.mode; delete cfg.min; delete cfg.max; delete cfg.step;
    delete cfg.payload_on; delete cfg.payload_off;
    delete cfg.state_on; delete cfg.state_off;
    cfg.entity_category = "diagnostic";
    if (kind === "binary") {
        cfg.payload_on = "True";
        cfg.payload_off = "False";
        return "binary_sensor";
    }
    cfg.unit_of_measurement = kind;
    if (kind === "s" || kind === "h") cfg.device_class = "duration";
    if (kind === "°C") cfg.device_class = "temperature";
    cfg.state_class = "measurement";
    return "sensor";
}

function createConfigPayload(key) {
    const cleanKey = key === "Device_address_N" ? "bms_device_address" : key.replace(/_[A-Z]+$/, "").toLowerCase();
    let entityType = key.endsWith("_B") ? "switch" : "number";
    const objectKey = key === "Device_address_N" ? "bms_device_address" : `bms_${cleanKey}`;

    const configPayload = {
        name: entityLabel(key === "Device_address_N" ? "bms_device_address" : key.replace(/_[A-Z]+$/, "")),
        unique_id: key === "Device_address_N" ? `${deviceID}_bms_device_address_v4` : `${deviceID}_bms_${cleanKey}_v4`,
        object_id: `${baseTopic.toLowerCase()}_${objectKey}`,
        default_entity_id: `${entityType}.${baseTopic.toLowerCase()}_${objectKey}`,
        state_topic: `${baseTopic}/control/${cleanKey}/state`,
        command_topic: `${baseTopic}/control/${cleanKey}/set`,
        entity_category: "config",
        device: {
            identifiers: [deviceID],
            name: deviceName,
            manufacturer: "Smartphoton-JK-BMS / ©JLM 2025-2026",
            model: payload.BMS_A || "JK-BMS - RS485 - Ip Gateway",
            sw_version: "3.5"
        }
    };

    if (entityType === "switch") {
        configPayload.payload_on = "True";
        configPayload.payload_off = "False";
        configPayload.state_on = "True";
        configPayload.state_off = "False";
        configPayload.icon = "mdi:toggle-switch";
    } else {
        configPayload.mode = "box";
        const meta = inferMeta(key);
        if (meta.unit !== undefined) configPayload.unit_of_measurement = meta.unit;
        if (meta.min !== undefined) configPayload.min = meta.min;
        if (meta.max !== undefined) configPayload.max = meta.max;
        if (meta.step !== undefined) configPayload.step = meta.step;
    }

    const readOnlyType = applyReadOnly(key, configPayload);
    if (readOnlyType) {
        entityType = readOnlyType;
        configPayload.default_entity_id = `${entityType}.${configPayload.object_id}`;
    }
    const configTopic = `${discoveryPrefix}/${entityType}/${deviceID}/${configPayload.object_id}/config`;

    return {
        topic: configTopic,
        payload: JSON.stringify(configPayload),
        retain: true
    };
}

function createStateMessage(key, value) {
    const cleanKey = key === "Device_address_N" ? "bms_device_address" : key.replace(/_[A-Z]+$/, "").toLowerCase();
    return {
        topic: `${baseTopic}/control/${cleanKey}/state`,
        payload: formatBoolean(value),
        retain: true
    };
}

// -----------------------------------------------------------------
// 4) Build the messages
// -----------------------------------------------------------------
let outMsgs = [];
let hasChanges = false;
let keys = Object.keys(payload).sort();

for (const key of keys) {
    const currentNormalized = normalizeValue(payload[key]);
    const previousNormalized = normalizeValue(lastSetup[key]);

    const keyWasKnown = Object.prototype.hasOwnProperty.call(lastSetup, key);
    const changed = !setupAlreadySent || forceRepublish || !keyWasKnown || currentNormalized !== previousNormalized;

    // Recreate config:
    // - on the first send
    // - on a forced republish
    // - when a new key appears
    if (!setupAlreadySent || forceRepublish || !keyWasKnown) {
        outMsgs.push(createConfigPayload(key));
    }

    // Publish state:
    // - on the first send
    // - on a forced republish
    // - on change
    if (changed) {
        outMsgs.push(createStateMessage(key, payload[key]));
        lastSetup[key] = payload[key];
        hasChanges = true;
    }
}

// -----------------------------------------------------------------
// 5) Save state / logs
// -----------------------------------------------------------------
if (!setupAlreadySent || forceRepublish || hasChanges) {
    flow.set(setupSentKey, true);
    flow.set(lastSetupKey, lastSetup);

    // Clear the force flags once used
    flow.set(forceKeyFlow, false);
    flow.set(forceAllKeyFlow, false);

    if (!setupAlreadySent) {
        node.warn(`✓ INITIAL setup sent for BMS ${slaveIdStr} (${outMsgs.length} messages)`);
    } else if (forceRepublish) {
        node.warn(`↻ Setup FORCED resend for BMS ${slaveIdStr} (${outMsgs.length} messages)`);
    } else {
        node.warn(`✓ Setup CHANGES detected for BMS ${slaveIdStr} (${outMsgs.length} messages)`);
    }

    return [outMsgs];
} else {
    node.debug(`⊘ Setup: no change for BMS ${slaveIdStr}`);
    return null;
}

// Check that the payload is a Buffer
if (Buffer.isBuffer(msg.payload)) {
    // Each byte as 2-digit hex
    msg.payload = msg.payload
        .toString('hex')                // whole buffer as one continuous hex string
        .match(/.{1,2}/g)               // split the string every 2 characters
        .join(' ') + '\n';              // space between bytes, newline at the end
} else if (Array.isArray(msg.payload)) {
    // Arrays are processed too
    msg.payload = msg.payload
        .map(x => x.toString(16).padStart(2, '0'))
        .join(' ') + '\n';
} else {
    // Otherwise do nothing (or raise an error)
    msg.payload = 'Payload non reconnu\n';
}
return msg;

// Process frames already extracted by the RS485 broadcast framer
// This node no longer reassembles frames
// It receives objects like:
// {
//   topic: "broadcast/jkbms_reply" | "broadcast/modbus_poll",
//   payload: <Buffer>,
//   hex: "...",
//   slave: 2
// }

function normalizeToBuffer(value) {
    if (Buffer.isBuffer(value)) {
        return value;
    }
    if (value && value.type === "Buffer" && Array.isArray(value.data)) {
        return Buffer.from(value.data);
    }
    if (Array.isArray(value)) {
        return Buffer.from(value);
    }
    return null;
}

// ISSUE #166: only complete SETUP frames with valid 0..15 identifiers can
// reach DATA, alarms, HA Discovery or the detected BMS list.
function normalizeBmsIdentifier(v) {
    if (!Number.isInteger(v) || v < 0 || v > 15) return null;
    return v === 0 ? "master" : String(v);
}

function refreshDetectedBms(id) {
    if (!id) return;
    const now = Date.now();
    const WINDOW_MS = 120 * 1000;
    let diag = flow.get("diag_serial_stats") || {};
    let seen = diag.detected_bms_seen || {};

    seen[id] = now;

    for (const [k, ts] of Object.entries(seen)) {
        if ((now - ts) > WINDOW_MS) {
            delete seen[k];
        }
    }

    const list = Object.keys(seen).sort((a, b) => {
        if (a === "master") return -1;
        if (b === "master") return 1;
        const na = Number(a), nb = Number(b);
        if (Number.isFinite(na) && Number.isFinite(nb)) return na - nb;
        return String(a).localeCompare(String(b));
    });

    diag.detected_bms_seen = seen;
    diag.detected_bms = list.length;
    diag.detected_bms_list = list.join(", ");
    flow.set("diag_serial_stats", diag);
}

const pendingDataKey = 'jkbms_pending_data';
let pendingData = context.get(pendingDataKey) || null;

// If the context restored a serialised object, normalise the payload
if (pendingData && pendingData.payload) {
    const normalizedPending = normalizeToBuffer(pendingData.payload);
    if (normalizedPending) {
        pendingData.payload = normalizedPending;
    } else {
        pendingData = null;
        context.set(pendingDataKey, null);
    }
}

if (pendingData && (!Number.isFinite(pendingData._issue1667_fallback_ts) ||
    Date.now() - pendingData._issue1667_fallback_ts > 12000 ||
    Date.now() < pendingData._issue1667_fallback_ts)) {
    issue1667RouteEvent("stale_pending_cleared", null, null);
    pendingData = null;
    context.set(pendingDataKey, null);
}

// The framer puts its object into msg.payload
const framed = msg.payload;

if (!framed || typeof framed !== "object" || !framed.topic || !framed.payload) {
    return null;
}

const frame = normalizeToBuffer(framed.payload);

if (!frame) {
    return null;
}

function typeTrame(byte) {
    if (byte === 1) return "setup";
    if (byte === 2) return "data";
    return "autre";
}

let outputFrames = [];
// ISSUE #166 — DEV166.8 STRICT BROADCAST REPLY INTEGRITY GATE.
// This gate runs ONLY in the Broadcast decoder; Active Polling is unchanged.
// Accepts the observed 308-byte JK body + 8-byte Modbus ACK profile.
// Also accepts a standalone 300-byte JK body if its checksum is correct;
// the absence of an ACK is recorded explicitly (not a successful CRC).
// Other lengths are rejected in THIS experimental build: 310-byte padded
// variants require independent validation before a general release.
// The Modbus CRC protects the ACK/address, NOT the 300-byte JK body.
function issue1668CheckReply(b166) {
    if (!Buffer.isBuffer(b166)) return {ok:false,reason:"not_buffer"};
    if (b166.length !== 308 && b166.length !== 300) {
        return {ok:false,reason:"unsupported_length",len:b166.length};
    }
    if (b166[0] !== 0x55 || b166[1] !== 0xAA ||
        b166[2] !== 0xEB || b166[3] !== 0x90) {
        return {ok:false,reason:"jk_header",len:b166.length};
    }
    const type166 = b166[4];
    if (type166 !== 1 && type166 !== 2) {
        return {ok:false,reason:"jk_type",len:b166.length};
    }
    let sum166 = 0;
    for (let j166 = 0; j166 < 299; j166++) {
        sum166 = (sum166 + b166[j166]) & 0xFF;
    }
    if (sum166 !== b166[299]) {
        return {ok:false,reason:"jk_checksum",len:b166.length,type:type166};
    }
    if (b166.length === 300) {
        // Native 300-byte JK reply: NO ACK, therefore CRC is unavailable.
        return {ok:true,profile:"jk300",type:type166,address:null};
    }
    if (b166[301] !== 0x10 || b166[302] !== 0x16 ||
        b166[304] !== 0 || b166[305] !== 1) {
        return {ok:false,reason:"ack_shape",len:308,type:type166};
    }
    if (b166[303] !== (type166 === 1 ? 0x1E : 0x20)) {
        return {ok:false,reason:"ack_register",len:308,type:type166};
    }
    if (b166[300] > 15) {
        return {ok:false,reason:"ack_address",len:308,type:type166};
    }
    let crc166 = 0xFFFF;
    for (let j166 = 300; j166 < 306; j166++) {
        crc166 ^= b166[j166];
        for (let bit166 = 0; bit166 < 8; bit166++) {
            crc166 = (crc166 & 1) ?
                ((crc166 >>> 1) ^ 0xA001) : (crc166 >>> 1);
        }
    }
    if ((crc166 & 0xFFFF) !== (b166[306] | (b166[307] << 8))) {
        return {ok:false,reason:"ack_crc",len:308,type:type166};
    }
    if (type166 === 1) {
        const setupAddress166 = b166.readUInt32LE(270);
        if (setupAddress166 > 15) {
            return {ok:false,reason:"setup_address",len:308,type:type166};
        }
        if (setupAddress166 !== b166[300]) {
            return {ok:false,reason:"setup_ack_mismatch",len:308,type:type166};
        }
    }
    return {ok:true,profile:"jk308",type:type166,address:b166[300]};
}

function issue1668GateRecord(result166) {
    try {
        const key166 = "issue1668_integrity_gate";
        const now166 = Date.now();
        let d166 = flow.get(key166);
        if (!d166 || d166.schema !== 1 || !d166.reasons) {
            d166 = {
                schema:1, since:now166, last_report_ts:0,
                seen:0, accepted_308:0, accepted_300_no_ack:0,
                rejected:0, reasons:{}, recent_rejections:[]
            };
        }
        d166.seen++;
        if (result166.ok) {
            if (result166.profile === "jk308") d166.accepted_308++;
            else if (result166.profile === "jk300") d166.accepted_300_no_ack++;
        } else {
            d166.rejected++;
            const reason166 = result166.reason || "unknown";
            d166.reasons[reason166] = (d166.reasons[reason166] || 0) + 1;
            d166.recent_rejections.push({
                ts:now166, reason:reason166,
                len:result166.len || null, type:result166.type || null
            });
            if (d166.recent_rejections.length > 8) d166.recent_rejections.shift();
            // Retain every rejection in state, but rate-limit operator warnings.
            if (!d166.last_reject_warn_ts ||
                now166 - d166.last_reject_warn_ts >= 60000) {
                node.warn("ISSUE1668_REJECT " + JSON.stringify({
                    reason:reason166, length:result166.len ?? null,
                    type:result166.type ?? null, rejected_total:d166.rejected
                }));
                d166.last_reject_warn_ts = now166;
            }
        }
        flow.set(key166,d166);
        // Summary first frame, then every 60 s; no raw frames or battery data.
        if (global.get('communication_debug') === true &&
            (!d166.last_report_ts || now166 - d166.last_report_ts >= 60000)) {
            node.log("ISSUE1668_INTEGRITY_GATE " + JSON.stringify({
                seen:d166.seen, accepted_308:d166.accepted_308,
                accepted_300_no_ack:d166.accepted_300_no_ack,
                rejected:d166.rejected, reasons:d166.reasons,
                recent_rejections:d166.recent_rejections.slice(-3)
            }));
            d166.last_report_ts = now166;
            flow.set(key166,d166);
        }
    } catch (e166) {
        // Diagnostics must not bypass the strict gate or modify frame routing.
        node.warn("ISSUE1668_INTEGRITY_GATE observer error: " + String(e166));
    }
}

// ISSUE #166 DEV166.7 — DIRECT BMS ADDRESS FOR STANDARD 308-BYTE DATA FRAMES.
// Reuse the CRC of the *trailing Modbus ACK* ONLY to establish who sent DATA.
// DO NOT activate strict whole-frame CRC/checksum rejection in this release.
// Unknown/variant formats continue through the existing Legacy fallback.
function issue1667DataAddress(b166) {
    if (!Buffer.isBuffer(b166) || b166.length !== 308 ||
        b166[0] !== 0x55 || b166[1] !== 0xAA ||
        b166[2] !== 0xEB || b166[3] !== 0x90 || b166[4] !== 2)
        return null;
    if (b166[301] !== 0x10 || b166[302] !== 0x16 ||
        b166[303] !== 0x20 || b166[304] !== 0 ||
        b166[305] !== 1 || b166[300] > 15) return null;
    let crc166 = 0xFFFF;
    for (let j166 = 300; j166 < 306; j166++) {
        crc166 ^= b166[j166];
        for (let bit166 = 0; bit166 < 8; bit166++) {
            crc166 = (crc166 & 1) ?
                ((crc166 >>> 1) ^ 0xA001) : (crc166 >>> 1);
        }
    }
    if ((crc166 & 0xFFFF) !== (b166[306] | (b166[307] << 8)))
        return null;
    return b166[300];
}

// Bounded, passive-style routing statistics; DOES NOT gate real decoder work.
function issue1667RouteEvent(event166, addr166, extra166) {
    try {
        const key166 = "issue1667_routing";
        const now166 = Date.now();
        let d166 = flow.get(key166);
        if (!d166 || d166.schema !== 1 || !d166.by_address) {
            d166 = {
                schema: 1, since: now166, last_report_ts: 0,
                direct_data: 0, legacy_fallback_data: 0,
                setup: 0, legacy_fallback_pair: 0,
                pending_cleared_on_direct: 0,
                stale_pending_cleared: 0,
                by_address: {}, recent_events: []
            };
        }
        if (Object.prototype.hasOwnProperty.call(d166, event166)) d166[event166]++;
        if (Number.isInteger(addr166) && addr166 >= 0 && addr166 <= 15) {
            const a166 = String(addr166);
            if (!d166.by_address[a166]) {
                d166.by_address[a166] = {
                    direct_data: 0, setup: 0, legacy_fallback_pair: 0
                };
            }
            if (Object.prototype.hasOwnProperty.call(d166.by_address[a166], event166))
                d166.by_address[a166][event166]++;
        }
        if (event166 !== "direct_data" && event166 !== "setup") {
            d166.recent_events.push({ts: now166, event: event166,
                address: addr166, detail: extra166 || null});
            if (d166.recent_events.length > 8) d166.recent_events.shift();
        }
        flow.set(key166, d166);
        if (global.get('communication_debug') === true &&
            (!d166.last_report_ts || now166 - d166.last_report_ts >= 60000)) {
            node.log("ISSUE1667_ROUTING " + JSON.stringify({
                direct_data: d166.direct_data,
                legacy_fallback_data: d166.legacy_fallback_data,
                setup: d166.setup,
                legacy_fallback_pair: d166.legacy_fallback_pair,
                pending_cleared_on_direct: d166.pending_cleared_on_direct,
                stale_pending_cleared: d166.stale_pending_cleared,
                by_address: d166.by_address,
                recent_events: d166.recent_events.slice(-3)
            }));
            d166.last_report_ts = now166;
            flow.set(key166, d166);
        }
    } catch (error166) {
        node.warn("ISSUE1667_ROUTING observer error: " + String(error166));
    }
}

// ISSUE #166 DEV166.6 — PASSIVE AUDIT OF THE EXISTING SINGLE pendingData.
// Installed as a helper in the real decoder, called BEFORE its original
// DATA overwrite and BEFORE its original SETUP pairing. No mutation of
// pendingData, frames, outputFrames, original context or MQTT routing.
function issue166AuditPairing(kind166, current166, previousPending166, setupId166) {
    try {
        const k166 = "issue166_pairing_passive";
        const now166 = Date.now();
        let d166 = flow.get(k166);
        if (!d166 || d166.schema !== 1 || !d166.by_address) {
            d166 = {
                schema: 1, since: now166, last_report_ts: 0,
                data_received: 0, setup_received: 0,
                data_overwritten: 0, setup_without_pending: 0,
                pairs: 0, pairs_match: 0, pairs_cross_address: 0,
                pairs_untrusted_data_address: 0,
                setup_ack_mismatch: 0, setup_ack_untrusted: 0,
                by_address: {}, recent_anomalies: []
            };
        }
        const add166 = (address166, name166) => {
            if (!Number.isInteger(address166) || address166 < 0 ||
                address166 > 15) return;
            const key166 = String(address166);
            let a166 = d166.by_address[key166];
            if (!a166) {
                a166 = {
                    data_received: 0, setup_received: 0,
                    data_overwritten: 0, matched_pairs: 0,
                    cross_pairs_as_data_source: 0,
                    cross_pairs_as_setup_destination: 0
                };
                d166.by_address[key166] = a166;
            }
            a166[name166]++;
        };
        const anomaly166 = (sample166) => {
            d166.recent_anomalies.push({ts: now166, ...sample166});
            if (d166.recent_anomalies.length > 8) {
                d166.recent_anomalies.shift();
            }
        };
        // Only trust the ACK address after verifying BOTH the JK body checksum
        // and its independent eight-byte Modbus trailer CRC + shape + register.
        const address166 = (b166, expectedKind166) => {
            if (!Buffer.isBuffer(b166) || b166.length !== 308 ||
                b166[0] !== 0x55 || b166[1] !== 0xAA ||
                b166[2] !== 0xEB || b166[3] !== 0x90 ||
                b166[4] !== (expectedKind166 === "data" ? 2 : 1))
                return null;
            let sum166 = 0;
            for (let j166 = 0; j166 < 299; j166++) {
                sum166 = (sum166 + b166[j166]) & 0xFF;
            }
            if (sum166 !== b166[299]) return null;
            const reg166 = expectedKind166 === "data" ? 0x20 : 0x1E;
            if (b166[301] !== 0x10 || b166[302] !== 0x16 ||
                b166[303] !== reg166 || b166[304] !== 0 ||
                b166[305] !== 1 || b166[300] > 15) return null;
            let crc166 = 0xFFFF;
            for (let j166 = 300; j166 < 306; j166++) {
                crc166 ^= b166[j166];
                for (let bit166 = 0; bit166 < 8; bit166++) {
                    crc166 = (crc166 & 1) ?
                        ((crc166 >>> 1) ^ 0xA001) : (crc166 >>> 1);
                }
            }
            if ((crc166 & 0xFFFF) !== (b166[306] | (b166[307] << 8)))
                return null;
            return b166[300];
        };
        const dataAddress166 = kind166 === "data" ?
            address166(current166, "data") :
            previousPending166 && previousPending166.payload ?
                address166(previousPending166.payload, "data") : null;

        if (kind166 === "data") {
            d166.data_received++;
            add166(dataAddress166, "data_received");
            if (previousPending166) {
                d166.data_overwritten++;
                const oldAddress166 = address166(previousPending166.payload, "data");
                add166(oldAddress166, "data_overwritten");
                anomaly166({
                    kind: "pending_data_overwrite",
                    old_data_address: oldAddress166,
                    new_data_address: dataAddress166
                });
            }
        } else if (kind166 === "setup") {
            d166.setup_received++;
            add166(setupId166, "setup_received");
            const setupAckAddress166 = address166(current166, "setup");
            if (setupAckAddress166 === null) d166.setup_ack_untrusted++;
            else if (setupAckAddress166 !== setupId166) {
                d166.setup_ack_mismatch++;
                anomaly166({
                    kind: "setup_identity_vs_ack",
                    setup_id: setupId166,
                    ack_address: setupAckAddress166
                });
            }
            if (!previousPending166) {
                d166.setup_without_pending++;
            } else {
                d166.pairs++;
                if (dataAddress166 === null) {
                    d166.pairs_untrusted_data_address++;
                    anomaly166({
                        kind: "pair_unknown_data_address",
                        assigned_setup_id: setupId166
                    });
                } else if (dataAddress166 === setupId166) {
                    d166.pairs_match++;
                    add166(dataAddress166, "matched_pairs");
                } else {
                    d166.pairs_cross_address++;
                    add166(dataAddress166, "cross_pairs_as_data_source");
                    add166(setupId166, "cross_pairs_as_setup_destination");
                    anomaly166({
                        kind: "cross_bms_pair",
                        real_data_address: dataAddress166,
                        assigned_setup_id: setupId166
                    });
                }
            }
        }

        flow.set(k166, d166);
        if (global.get('communication_debug') === true &&
            (!d166.last_report_ts || now166 - d166.last_report_ts >= 60000)) {
            node.log("ISSUE166_PAIRING_PASSIVE " + JSON.stringify({
                data_received: d166.data_received,
                setup_received: d166.setup_received,
                data_overwritten: d166.data_overwritten,
                setup_without_pending: d166.setup_without_pending,
                pairs: d166.pairs,
                pairs_match: d166.pairs_match,
                pairs_cross_address: d166.pairs_cross_address,
                pairs_untrusted_data_address: d166.pairs_untrusted_data_address,
                setup_ack_mismatch: d166.setup_ack_mismatch,
                setup_ack_untrusted: d166.setup_ack_untrusted,
                by_address: d166.by_address,
                recent_anomalies: d166.recent_anomalies.slice(-3)
            }));
            d166.last_report_ts = now166;
            flow.set(k166, d166);
        }
    } catch (e166) {
        node.warn("ISSUE166_PAIRING_PASSIVE observer error: " + String(e166));
    }
}


// --------------------------------------------------
// 1) Short Modbus request
// --------------------------------------------------
if (framed.topic === "broadcast/modbus_poll") {
    let reqMsg = {
        payload: Buffer.from(frame),
        bms_adresse: frame[0],
        bms_type: "requete",
        _frameSource: "REQUETE",
        _frameLength: frame.length,
        _hex: framed.hex || frame.toString("hex")
    };

    return reqMsg;
}

// --------------------------------------------------
// 2) JK-BMS reply
// --------------------------------------------------
if (framed.topic === "broadcast/jkbms_reply") {
    const result1668 = issue1668CheckReply(frame);
    issue1668GateRecord(result1668);
    if (!result1668.ok) {
        // A rejected frame must not leave an older DATA to be falsely
        // paired with a later SETUP. No MQTT payload is emitted.
        if (pendingData) {
            pendingData = null;
            context.set(pendingDataKey, null);
        }
        return null;
    }
    // Minimal header check
    if (
        frame.length < 6 ||
        frame[0] !== 0x55 ||
        frame[1] !== 0xAA ||
        frame[2] !== 0xEB ||
        frame[3] !== 0x90
    ) {
        return null;
    }

    const frameType = typeTrame(frame[4]);

    if (frameType === "data") {
        // The DATA buffer parser reads byte 281 (minimum 282 bytes).
        if (frame.length < 282) {
            context.set(pendingDataKey, null);
            node.warn("ISSUE #166: truncated DATA frame (" + frame.length + " bytes), dropped");
            return null;
        }
        const directId1667 = issue1667DataAddress(frame);
        if (directId1667 !== null) {
            if (pendingData) {
                issue1667RouteEvent("pending_cleared_on_direct", directId1667, null);
                pendingData = null;
                context.set(pendingDataKey, null);
            }
            refreshDetectedBms(normalizeBmsIdentifier(directId1667));
            issue1667RouteEvent("direct_data", directId1667, null);
            return {
                payload: Buffer.from(frame),
                bms_adresse: framed.slave !== undefined ? framed.slave : "master",
                bms_type: "data",
                bms_numero: directId1667,
                _frameSource: "JK-BMS",
                _frameLength: frame.length,
                _hex: framed.hex || frame.toString("hex")
            };
        }
        issue1667RouteEvent("legacy_fallback_data", null, {length: frame.length});
        issue166AuditPairing("data", frame, pendingData, null);
        // Buffer the data until the next setup frame
        pendingData = {
            payload: Buffer.from(frame),
            bms_adresse: framed.slave !== undefined ? framed.slave : "master",
            bms_type: "data",
            _frameSource: "JK-BMS",
            _frameLength: frame.length,
            _hex: framed.hex || frame.toString("hex"),
            _issue1667_fallback_ts: Date.now()
        };

        context.set(pendingDataKey, pendingData);
        return null;
    }

    if (frameType === "setup") {
        // SETUP parser reads byte 283 (minimum 284 bytes).
        if (frame.length < 284) {
            context.set(pendingDataKey, null);
            node.warn("ISSUE #166: truncated SETUP frame (" + frame.length + " bytes), dropped");
            return null;
        }
        // BMS index is unsigned uint32 LE at offsets 270..273.
        const bmsNumber = frame.readUInt32LE(270);
        const normalizedId = normalizeBmsIdentifier(bmsNumber);
        if (normalizedId === null) {
            context.set(pendingDataKey, null);
            node.warn("ISSUE #166: invalid SETUP BMS address " + bmsNumber + ", dropped");
            return null;
        }
        issue1667RouteEvent("setup", bmsNumber, null);
        if (pendingData) {
            issue1667RouteEvent("legacy_fallback_pair", bmsNumber, null);
            issue166AuditPairing("setup", frame, pendingData, bmsNumber);
        }
        refreshDetectedBms(normalizedId);

        // First send the buffered DATA with the right number
        if (pendingData) {
            // DEV166.7 internal fallback metadata must not enter downstream.
            delete pendingData._issue1667_fallback_ts;
            pendingData.bms_numero = bmsNumber;
            outputFrames.push(pendingData);
            pendingData = null;
            context.set(pendingDataKey, null);
        }

        // Then send the SETUP
        let setupMsg = {
            payload: Buffer.from(frame),
            bms_adresse: framed.slave !== undefined ? framed.slave : "master",
            bms_type: "setup",
            bms_numero: bmsNumber,
            _frameSource: "JK-BMS",
            _frameLength: frame.length,
            _hex: framed.hex || frame.toString("hex")
        };

        outputFrames.push(setupMsg);

        if (outputFrames.length === 1) {
            return outputFrames[0];
        }
        return [outputFrames];
    }

    return null;
}

return null;

// TOTAL number of configured JK-BMS.
let totalBms = Number(global.get("nb_jkbms")) || 1;
totalBms = Math.max(1, Math.floor(totalBms));

const broadcasting =
    global.get("bms_broadcasting") === true ||
    global.get("bms_broadcasting") === "true" ||
    global.get("bms_broadcasting") === 1 ||
    global.get("bms_broadcasting") === "1";

function getSlaveAddressesToReset() {
    // In broadcasting mode the master (address 0) counts in nb_jkbms.
    // ISSUE #180: prefer the addresses actually seen in SETUP,
    // so that both Master+BMS_1 and older installations are supported
    // Master+BMS_2, and non-consecutive addresses.
    if (broadcasting) {
        const neededSlaves = Math.max(0, totalBms - 1);
        if (neededSlaves === 0) return { addresses: [], detected: true };

        const now = Date.now();
        const MAX_AGE_MS = 120 * 1000;
        const seen = global.get("premium.dashboard_bms_seen");

        if (seen && typeof seen === "object" && !Array.isArray(seen)) {
            const candidates = Object.entries(seen)
                .filter(([id, ts]) => {
                    const n = Number(id);
                    const t = Number(ts);
                    return id !== "master" &&
                        Number.isInteger(n) && n >= 1 && n <= 15 &&
                        Number.isFinite(t) && (now - t) <= MAX_AGE_MS;
                })
                .map(([id, ts]) => ({ address: Number(id), ts: Number(ts) }))
                .sort((a, b) => b.ts - a.ts);

            if (candidates.length >= neededSlaves) {
                const addresses = candidates
                    .slice(0, neededSlaves)
                    .map(x => x.address)
                    .sort((a, b) => a - b);
                return { addresses, detected: true };
            }
        }

        // Conservative fallback: previous behaviour.
        // Resetting one flag too many is better than missing
        // an older installation whose slave is, for example, BMS_2.
        return {
            addresses: Array.from({ length: totalBms }, (_, i) => i + 1),
            detected: false
        };
    }

    // Without broadcasting nb_jkbms means BMS 1..N.
    return {
        addresses: Array.from({ length: totalBms }, (_, i) => i + 1),
        detected: true
    };
}

const target = getSlaveAddressesToReset();

// -------------------------
// RESET DATA MASTER
// -------------------------
flow.set("discoverySent_BMS_master", false);
flow.set("discoveredKeys_BMS_master", []);

// -------------------------
// RESET ALARMES MASTER
// -------------------------
flow.set("discoverySent_ALARMS_BMS_master", false);
flow.set("lastAlarmState_BMS_master", null);

// -------------------------
// RESET SLAVE BMS
// -------------------------
for (const i of target.addresses) {
    // DATA
    flow.set(`discoverySent_BMS_${i}`, false);
    flow.set(`discoveredKeys_BMS_${i}`, []);

    // ALARMES
    flow.set(`discoverySent_ALARMS_BMS_${i}`, false);
    flow.set(`lastAlarmState_BMS_${i}`, null);
}

// -------------------------
// RESET GLOBAL
// -------------------------
flow.set("discoverySent_GLOBAL_ALARM", false);
flow.set("lastGlobalAlarmState", null);

const slavesText = target.addresses.length
    ? target.addresses.map(i => `BMS_${i}`).join(", ")
    : "no slave";
const fallbackText = target.detected ? "" : " (fallback conservateur)";

node.warn(`Discovery reset done for DATA + ALARMS + GLOBAL on Master + ${slavesText}${fallbackText}.`);
return msg;

var BMS = msg.payload["Device_address_N"];
// Debug: show the BMS value
node.warn(`BMS Nb:${BMS} is alive`);
return msg;

// ISSUE #166: prevent bad BMS IDs from reaching any MQTT or state path.
const raw166 = msg.bms_numero;
const parsed166 = (typeof raw166 === "string" && raw166.toLowerCase() === "master")
    ? 0 : (typeof raw166 === "number" || (typeof raw166 === "string" && /^(0|[1-9]|1[0-5])$/.test(raw166)))
        ? Number(raw166) : NaN;
if (!Number.isInteger(parsed166) || parsed166 < 0 || parsed166 > 15) {
    node.warn("ISSUE #166: invalid alarm BMS identifier " + String(raw166) + ", dropped");
    return null;
}
msg.bms_numero = parsed166;

const errorList = [
    "Balancing resistance too high",               // bit 0
    "MOS over-temperature protection",             // bit 1
    "Number of cells does not match parameter",    // bit 2
    "Abnormal current sensor",                     // bit 3
    "Cell over-voltage protection",                // bit 4
    "Battery over-voltage protection",             // bit 5
    "Overcurrent charge protection",               // bit 6
    "Charge short-circuit protection",             // bit 7
    "Over-temperature charge protection",          // bit 8
    "Low temperature charge protection",           // bit 9
    "Internal communication anomaly",              // bit 10
    "Cell under-voltage protection",               // bit 11
    "Battery under-voltage protection",            // bit 12
    "Overcurrent discharge protection",            // bit 13
    "Discharge short-circuit protection",          // bit 14
    "Over-temperature discharge protection",       // bit 15
    "Charge MOS anomaly",                          // bit 16
    "Discharge MOS anomaly",                       // bit 17
    "GPS disconnected",                            // bit 18
    "Please modify the authorization password in time", // bit 19
    "Discharge activation failure",                // bit 20
    "Battery over-temperature alarm",              // bit 21
    "Temperature sensor anomaly",                  // bit 22
    "Parallel module anomaly",                     // bit 23
    "Reserved bit 24",
    "Reserved bit 25",
    "Reserved bit 26",
    "Reserved bit 27",
    "Reserved bit 28",
    "Reserved bit 29",
    "Reserved bit 30",
    "Reserved bit 31"
];

const buffer = msg.payload;
if (buffer.length <= 169) {
    msg.payload = { error: "Buffer too small to extract error code", bms_address: msg.bms_adresse };
    return msg;
}

// Swap bytes as requested
const swappedErrorCode =
    (buffer[169] << 24) |
    (buffer[168] << 16) |
    (buffer[167] << 8) |
    (buffer[166]);

const activeErrors = [];
for (let i = 0; i < errorList.length; i++) {
    if (swappedErrorCode & (1 << i)) {
        activeErrors.push(errorList[i]);
    }
}

// Build the payload in the "reference" format
// Do not include the "🚨 BMS Alarm Alert" prefix in the errors array
msg.payload = {
    bms_address: msg.bms_numero,
    error_code: swappedErrorCode,
    errors: activeErrors.length > 0 ? activeErrors : []
};

return msg;

// ====== ALARM PROCESSING ======

const p = msg.payload || {};

// ------------------------------------------------------------------
// VALIDATION / NORMALISATION
const errorCode = Number(p.error_code);
if (!Number.isFinite(errorCode)) {
    node.error("Invalid payload: error_code missing");
    return [null, null];
}

let bmsNumeroRaw = msg.bms_numero;
let bmsId;
let bmsName;

if (typeof bmsNumeroRaw === "string" && bmsNumeroRaw.toLowerCase() === "master") {
    bmsId = 0;
} else if (typeof bmsNumeroRaw === "number" ||
           (typeof bmsNumeroRaw === "string" && /^(0|[1-9]|1[0-5])$/.test(bmsNumeroRaw))) {
    bmsId = Number(bmsNumeroRaw);
} else {
    bmsId = NaN;
}
if (!Number.isInteger(bmsId) || bmsId < 0 || bmsId > 15) {
    node.warn("ISSUE #166: invalid BMS alarm identifier " + String(bmsNumeroRaw) + ", dropped");
    return [null, null];
}
bmsName = bmsId === 0 ? "BMS_master" : "BMS_" + bmsId;

// ------------------------------------------------------------------
// STORAGE KEYS FOR CHANGE DETECTION
const discoveryKey = `discoverySent_ALARMS_${bmsName}`;
const lastAlarmStateKey = `lastAlarmState_${bmsName}`;

const discoveryAlreadySent = flow.get(discoveryKey) || false;
const lastAlarmState = flow.get(lastAlarmStateKey) || null;

// ------------------------------------------------------------------
// CONVERT TO THE INTERNAL FORMAT
const hasAlarms = errorCode !== 0;
const errorList = Array.isArray(p.errors) ? p.errors : [];
const alarmCount = hasAlarms ? errorList.length : 0;

const alarmData = {
    bms_id: bmsId,
    has_alarms: hasAlarms,
    alarm_count: alarmCount,
    active_alarms: hasAlarms ? errorList.map(e => ({ description: e })) : [],
    alarm_details: {
        status: hasAlarms ? "🚨 BMS Alarm Alert" : "No BMS alarms"
    }
};

// ------------------------------------------------------------------
// CHANGE DETECTION
const currentStateSignature = JSON.stringify({
    error_code: errorCode,
    errors: errorList
});

const hasChanged = (lastAlarmState !== currentStateSignature);

// ------------------------------------------------------------------
// NO CHANGE AND ALREADY SENT -> EXIT
msg.alarms = alarmData;
msg.bms_name = bmsName;
msg.bms_id = bmsId;

if (!hasChanged && discoveryAlreadySent) {
    node.debug(`⊘ Alarms ${bmsName}: no change (error_code: ${errorCode})`);
    return [null, msg];
}

// ------------------------------------------------------------------
// SOMETHING CHANGED OR THIS IS THE FIRST SEND
if (hasChanged) {
    if (lastAlarmState === null) {
        node.warn(`✓ Alarmes ${bmsName}: INITIAL (error_code: ${errorCode})`);
    } else {
        node.warn(`✓ Alarms ${bmsName}: CHANGE detected (${errorCode === 0 ? 'alarms cleared' : alarmCount + ' alarm(s)'})`);
    }
}

flow.set(lastAlarmStateKey, currentStateSignature);

// ------------------------------------------------------------------
// DISCOVERY / MQTT
const baseTopic = bmsName;
const discoveryPrefix = "homeassistant";
const deviceID = `${bmsName}_device`;

function buildDiscovery() {
    const m = [];

    m.push({
        topic: `${discoveryPrefix}/binary_sensor/${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_active/config`,
        payload: {
            name: `${bmsName} Alarm Active`,
            unique_id: `${deviceID}_alarm_active_v2`,
            object_id: `${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_active`,
            default_entity_id: `binary_sensor.${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_active`,
            state_topic: `${baseTopic}/alarm/active`,
            payload_on: "ON",
            payload_off: "OFF",
            device_class: "problem",
            icon: "mdi:alert-circle",
            device: {
                identifiers: [deviceID],
                name: bmsName
            }
        },
        retain: true
    });

    m.push({
        topic: `${discoveryPrefix}/sensor/${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_visual_status/config`,
        payload: {
            name: `${bmsName} Visual Status`,
            unique_id: `${deviceID}_visual_status_v2`,
            object_id: `${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_visual_status`,
            default_entity_id: `sensor.${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_visual_status`,
            state_topic: `${baseTopic}/alarm/visual_status`,
            icon: "mdi:gauge",
            device: {
                identifiers: [deviceID],
                name: bmsName
            }
        },
        retain: true
    });

    m.push({
        topic: `${discoveryPrefix}/sensor/${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_status/config`,
        payload: {
            name: `${bmsName} Alarm Status`,
            unique_id: `${deviceID}_alarm_status_v2`,
            object_id: `${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_status`,
            default_entity_id: `sensor.${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_status`,
            state_topic: `${baseTopic}/alarm/status`,
            icon: "mdi:text-box-outline",
            device: {
                identifiers: [deviceID],
                name: bmsName
            }
        },
        retain: true
    });

    m.push({
        topic: `${discoveryPrefix}/sensor/${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_list/config`,
        payload: {
            name: `${bmsName} Alarm List`,
            unique_id: `${deviceID}_alarm_list_v2`,
            object_id: `${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_list`,
            default_entity_id: `sensor.${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_list`,
            state_topic: `${baseTopic}/alarm/list`,
            icon: "mdi:format-list-bulleted",
            device: {
                identifiers: [deviceID],
                name: bmsName
            }
        },
        retain: true
    });

    return m;
}

function buildState() {
    const out = [];

    out.push({
        topic: `${baseTopic}/alarm/active`,
        payload: alarmData.has_alarms ? "ON" : "OFF",
        retain: true
    });

    out.push({
        topic: `${baseTopic}/alarm/visual_status`,
        payload: alarmData.has_alarms
            ? `🚨 ${alarmData.alarm_count} alarme(s)`
            : "✅ No alarm",
        retain: true
    });

    out.push({
        topic: `${baseTopic}/alarm/status`,
        payload: alarmData.alarm_details.status,
        retain: true
    });

    out.push({
        topic: `${baseTopic}/alarm/list`,
        payload: alarmData.active_alarms.length > 0
            ? alarmData.active_alarms.map(a => a.description).join(", ")
            : "No alarms",
        retain: true
    });

    return out;
}

// ------------------------------------------------------------------
// PREPARE OUTPUTS
const mqttMsgs = [];

if (!discoveryAlreadySent) {
    mqttMsgs.push(...buildDiscovery());
    flow.set(discoveryKey, true);
}

mqttMsgs.push(...buildState());

// sortie 1 = MQTT
// output 2 = enriched msg for the global aggregation
return [mqttMsgs, msg];

// ===== GLOBAL ALARM AGGREGATION - OPTIMISED VERSION =====
// ✓ Sent at start-up
// ✓ Sent ONLY if global status changes
// ✓ Massive savings in MQTT messages

const alarmData = msg.alarms;
if (!alarmData || alarmData.bms_id === undefined || alarmData.bms_id === null) {
    return null;
}

const bmsId = alarmData.bms_id;
const now = Date.now();

// Number of slave BMS (without master)
const TOTAL_BMS = global.get("nb_jkbms") || 4;

// Max time (ms) without a message before a BMS is left out
const TIMEOUT_MS = 15000;

// ------------------------------------------------------------------
// STORE STATE + TIMESTAMP FOR THIS BMS
flow.set(`bms_alarm_state_${bmsId}`, {
    has_alarm: alarmData.has_alarms,
    alarm_count: alarmData.alarm_count,
    last_seen: now
});

// ------------------------------------------------------------------
// COMPUTE GLOBAL STATE
let globalHasAlarm = false;
let activeAlarmsList = []; // for debug/logs

for (let i = 0; i <= TOTAL_BMS; i++) {
    const s = flow.get(`bms_alarm_state_${i}`);
    if (!s) continue;

    // Ignore a BMS that has been silent for too long
    if ((now - s.last_seen) > TIMEOUT_MS) continue;

    if (s.has_alarm) {
        globalHasAlarm = true;
        activeAlarmsList.push(`BMS_${i === 0 ? 'master' : i}`);
    }
}

// ------------------------------------------------------------------
// CHANGE DETECTION
const lastGlobalStateKey = "lastGlobalAlarmState";
const lastGlobalState = flow.get(lastGlobalStateKey);

const currentGlobalState = globalHasAlarm ? "ON" : "OFF";
const hasChanged = (lastGlobalState !== currentGlobalState);

// ------------------------------------------------------------------
// NO CHANGE AND ALREADY SENT -> EXIT
if (!hasChanged && lastGlobalState !== null) {
    node.debug(`⊘ GLOBAL alarm: No change (state: ${currentGlobalState})`);
    return null;
}

// ------------------------------------------------------------------
// SOMETHING CHANGED OR THIS IS THE FIRST SEND
if (hasChanged) {
    if (lastGlobalState === null) {
        node.warn(`✓ GLOBAL alarm: INITIAL (${currentGlobalState})`);
    } else {
        if (globalHasAlarm) {
            node.warn(`🚨 GLOBAL alarm: ON (BMS concerned: ${activeAlarmsList.join(', ')})`);
        } else {
            node.warn(`✅ GLOBAL alarm: OFF (all alarms cleared)`);
        }
    }
}

// Save the new state
flow.set(lastGlobalStateKey, currentGlobalState);

// ------------------------------------------------------------------
// MQTT / HOME ASSISTANT
const discoveryPrefix = "homeassistant";
const globalDeviceID = "BMS_GLOBAL_device";
const messages = [];

// ------------------------------------------------------------------
// DISCOVERY (once)
if (!flow.get("discoverySent_GLOBAL_ALARM")) {
    messages.push({
        topic: `${discoveryPrefix}/binary_sensor/${globalDeviceID}/alarm_active/config`,
        payload: {
            name: "BMS Global Alarm",
            unique_id: `${globalDeviceID}_alarm_active`,
            state_topic: "BMS_GLOBAL/alarm/state",
            payload_on: "ON",
            payload_off: "OFF",
            device_class: "problem",
            icon: "mdi:battery-alert",
            device: {
                identifiers: [globalDeviceID],
                name: "BMS Global"
            }
        },
        retain: true
    });

    flow.set("discoverySent_GLOBAL_ALARM", true);
    node.warn("✓ Discovery GLOBAL ALARM sent");
}

// ------------------------------------------------------------------
// PUBLISH GLOBAL STATE (only if changed)
messages.push({
    topic: "BMS_GLOBAL/alarm/state",
    payload: currentGlobalState,
    retain: true
});

return [messages];

// ========== FILTRE DE VALIDATION BMS_NUMERO ==========
// Place AFTER the buffer-parser, BEFORE the processing nodes
// Check that msg.bms_numero is between 0 and 15
// Block and report any invalid value

const bmsNumero = msg.bms_numero;

// ------------------------------------------------------------------
// VALIDATION TYPE
if (bmsNumero === undefined || bmsNumero === null) {
    node.error(`❌ INVALID BMS_NUMERO: missing value (undefined/null)`, msg);
    node.warn(`Payload received: ${JSON.stringify(msg.payload)}`);
    return null; // block the message
}

// Convert to number if it is a string
let bmsNum;
if (typeof bmsNumero === "string") {
    bmsNum = /^(0|[1-9]|1[0-5])$/.test(bmsNumero) ? Number(bmsNumero) : NaN;
    if (!Number.isInteger(bmsNum)) {
        node.error(`❌ INVALID BMS_NUMERO: non-numeric string "${bmsNumero}"`, msg);
        return null;
    }
    // Correction automatique
    msg.bms_numero = bmsNum;
    node.warn(`⚠️ BMS_NUMERO converti: "${bmsNumero}" → ${bmsNum}`);
} else if (typeof bmsNumero === "number") {
    if (isNaN(bmsNumero)) {
        node.error(`❌ INVALID BMS_NUMERO: NaN`, msg);
        return null;
    }
    bmsNum = bmsNumero;
} else {
    node.error(`❌ INVALID BMS_NUMERO: wrong type (${typeof bmsNumero})`, msg);
    return null;
}

