        }
        const b166 = f166.payload;
        const len166 = b166.length;
        const type166 = b166[4] === 1 ? "setup" : b166[4] === 2 ? "data" : "other";
        d166.frames++;
        d166.types[type166]++;
        d166.last_frame_ts = now166;
        const lenKey166 = String(len166);
