// Build the Modbus write frame
// Input: msg.payload is the voltage (e.g. 3.42)
function generateModbusWriteCommand(voltage) {
    // Modbus CRC16
    function crc16(buffer) {
        let crc = 0xFFFF;
        for (let i = 0; i < buffer.length; i++) {
            crc ^= buffer[i];
            for (let j = 0; j < 8; j++) {
                if (crc & 0x0001) {
                    crc = (crc >> 1) ^ 0xA001;
                } else {
                    crc = crc >> 1;
                }
            }
        }
        return crc;
    }

    // Voltage as integer (scale 1/1000)
    const voltageValue = Math.round(voltage * 1000);

    // Build the frame without CRC
    // Slave address from the global context
    const slaveId = global.get("slaveAddress-setup") || 0x01; // default if not set

    const command = [
        slaveId,                           // Slave ID
        0x10,                           // Function code (16/0x10 - Write Multiple Registers)
        0x10,                           // Register address high byte (0x10)
        0x84,                           // Register address low byte (0x84)
        0x00,                           // quantity high byte (2 registers for uint32)
        0x02,                           // quantity low byte (2 registers for uint32)
        0x04,                           // byte count (4 bytes for uint32)
        (voltageValue >> 24) & 0xFF,    // MSB (first byte)
        (voltageValue >> 16) & 0xFF,    // second byte
        (voltageValue >> 8) & 0xFF,     // third byte
        voltageValue & 0xFF             // LSB (last byte)
    ];

    // CRC
    const crc = crc16(Buffer.from(command));

    // Append the CRC (little-endian)
    command.push(crc & 0xFF);          // CRC low byte
    command.push((crc >> 8) & 0xFF);   // CRC high byte

    return Buffer.from(command);
}

