    node.error(`Register 0x1114 of BMS ${slaveId} not read yet - write refused to avoid clearing other switches`);
    return null;
}
const current = row[0] & 0xFFFF;
const next = enable ? (current | BIT_MASK) : (current & ~BIT_MASK);
row[0] = next;
global.set("0x1114", table);

