msg.headers = { "Content-Type": "application/json" };
node.status({fill: statusColor, shape: "dot", text: msg.environment});
return msg;

const lang = String(global.get("ui.language") || "en");
const texts = global.get("ui_text") || {};
const t = texts[lang] || texts.en || {};
const p = msg.payload || {};
const bmsAddress = global.get("slaveAddress-Trame3") || "BMS-Unknown";
const num = v => (Number.isFinite(Number(v)) ? Number(v) : 0);

// Cell voltages
const cellCount = num(p.cell_count_N) || 16;
const voltages = [];
for (let i = 1; i <= cellCount; i++) {
    const v = Number(p[`Cell_${i}_volt_V`]);
    if (Number.isFinite(v) && v > 0) voltages.push({ cell: i, voltage: Math.round(v * 1000) / 1000 });
}
const values = voltages.map(c => c.voltage);
const min = values.length ? Math.min(...values) : 0;
const max = values.length ? Math.max(...values) : 0;
const average = values.length ? values.reduce((a, b) => a + b, 0) / values.length : 0;

// Temperatures
const sensors = [{ name: t.mosfet || "MOSFET", value: p.Mos_temp_T }];
for (let i = 1; i <= 5; i++) {
    const value = i === 5 ? p.Temp_sensor_5_T : p[`Sonde_${i}_temp_T`];
    sensors.push({ name: `${t.sensor || "Sensor"} ${i}`, value });
}
const temps = sensors.filter(s => Number.isFinite(Number(s.value))).map(s => ({ name: s.name, value: Number(s.value) }));

// Runtime as "1d 02h 03m"
const runtimeS = num(p.Total_runtime_S);
const d = Math.floor(runtimeS / 86400), h = Math.floor((runtimeS % 86400) / 3600), m = Math.floor((runtimeS % 3600) / 60);
const runtimeText = `${d}${t.days || "d"} ${String(h).padStart(2, "0")}${t.hours || "h"} ${String(m).padStart(2, "0")}${t.minutes || "m"}`;

msg.t = t;
msg.payload = {
    bmsAddress,
    timestamp: new Date().toISOString(),
    cellCount,
    voltage: num(p.Tension_Totale_volt_V),
    current: num(p.Courant_total_A),
    power: Number.isFinite(p.Battery_power_W) ? p.Battery_power_W : num(p.Puissance_Totale_W),
    soc: num(p.SOC_pourcentage_P),
    soh: num(p.SOH_pourcentage_P),
    capacity: { remaining: num(p.Capacite_restante_Ah), total: num(p.Capacite_batterie_Ah) },
    cells: { voltages, min, max, average, delta: Math.round((max - min) * 1000) / 1000 },
    temperatures: {
        sensors: temps,
        max: temps.length ? Math.max(...temps.map(x => x.value)) : 0,
        min: temps.length ? Math.min(...temps.map(x => x.value)) : 0
    },
    switches: [
        { label: t.charge || "Charge", on: p.Switch_Charge_B === 1 },
        { label: t.discharge || "Discharge", on: p.Switch_Decharge_B === 1 },
        { label: t.balancing || "Balancing", on: p.Balance_Action_B === 1 },
        { label: t.precharge || "Precharge", on: p.Precharging_B === 1 },
        { label: t.heating || "Heating", on: p.Heating_B === 1 },
        { label: t.charger || "Charger plugged in", on: p.Charger_plugged_B === 1 }
    ],
    balance: { current: num(p.Balance_courant_A), active: p.Balance_Action_B === 1, status: p.Balancer_status_text_S || "" },
    maintenance: { cycles: num(p.Nombre_Cycle_N), cycleCapacity: num(p.Cycle_Capacite_Ah), runtimeSeconds: runtimeS, runtimeText }
};
return msg;

const lang = String(global.get("ui.language") || "en");
const texts = global.get("ui_text") || {};
const t = texts[lang] || texts.en || {};
const bmsAddress = global.get("slaveAddress-Trame1") || "1";
const d = msg.payload || {};
const uptime = Number(d.Uptime_S) || 0;
const days = Math.floor(uptime / 86400);
const hours = Math.floor((uptime % 86400) / 3600);

msg.t = t;
msg.payload = {
    bmsAddress,
    timestamp: new Date().toISOString(),
    model: d.BMS_A,
    serial: d.SerialNb_N,
    brand: d.Brand_A,
    firmware: d.FW_A,
    software: d.SW_N,
    powerCount: d.Power_count_N,
    uptime: `${days}${t.days || "d"} ${hours}${t.hours || "h"}`,
    manufacturingDate: d.Manufacturing_date_N,
    buzzer: { trigger: d.LCD_buzzer_trigger_value_N, release: d.LCD_buzzer_release_value_N },
    params: { rcvTimeHours: d.Request_Charge_voltage_Time_H, rfvTimeHours: d.Request_Float_voltage_Time_H, canProtocol: d.CAN_protocol_number_N }
};
return msg;

const lang = String(global.get("ui.language") || "en");
const texts = global.get("ui_text") || {};
const t = texts[lang] || texts.en || {};
// BMS id for the "Sort settings by BMS" switch
const bmsId = (msg.payload && msg.payload.Device_address_N) || "1";
msg.bmsAddress = bmsId.toString();
msg.t = t;
return msg;

// Legacy 4.1.12-alpha4: 4 standalone INT32 thresholds + two guarded source registers.
const topic=String(msg.topic||'');
const m=/^BMS_(\d+)\/control\/(dry[12]_(?:(?:trigger|release)_value|trigger_code))\/set$/i.exec(topic);
if(!m) return null;
const id=Number(m[1]), key=m[2].toLowerCase();
if(!Number.isInteger(id)||id<1||id>15){node.warn('DRY invalid BMS address');return null;}
if(global.get('bms_broadcasting')===true){node.warn('DRY write blocked: Broadcasting');return null;}
if(global.get('Authorize_Modify_Settings')!==true){node.warn('DRY write blocked: Modify Settings disabled');return null;}
const raw=String(msg.payload).trim();
const dryLabels = ["00 - OFF", "01 - Low SOC", "02 - Battery Over Voltage", "03 - Battery Under Voltage", "04 - Battery Cell Over Voltage", "05 - Battery Cell Under Voltage", "06 - Charge Over Current", "07 - Discharge Over Current", "08 - Battery over Temperature", "09 - MOSFET Over Temperature", "10 - SysAlarm", "11 - Battery Low Temperature", "12 - Remote Control", "13 - Above SOC", "14 - MOSFET Abnormal"];
const sourceCommand = key==='dry1_trigger_code' || key==='dry2_trigger_code';
let val;
if (sourceCommand) {
    const index=dryLabels.indexOf(raw);
    if (index>=0) val=index;
    else if (/^\d{1,2}$/.test(raw) && Number(raw)<=14) val=Number(raw);
    else {node.warn('DRY unknown source label/code');return null;}
} else {
    if(!/^-?\d+$/.test(raw)){node.warn('DRY integer required');return null;}
    val=Number(raw);
}
// Brief suppression of exactly identical repeated MQTT commands.
// alpha6: only one outstanding command per physical BMS/parameter.
const pendingKey='dry_alpha6_pending_BMS_'+id+'_'+key;
const outstanding=global.get(pendingKey);
if(outstanding && Number.isFinite(outstanding.deadline) && Date.now()<outstanding.deadline) {
    // Duplicate MQTT deliveries for the same requested value are harmless.
    // Preserve the safety lock if the user requests a different value mid-flight.
    if (outstanding.requested === val) {
        node.debug('DRY duplicate MQTT command ignored while STATIC verification is pending: '+key+' BMS_'+id);
    } else {
        node.warn('DRY write blocked: previous write awaiting STATIC readback '+key+' BMS_'+id);
    }
    return null;
}
const dedupKey='dry_alpha5_last_cmd_BMS_'+id+'_'+key;
const prev=context.get(dedupKey);
const now=Date.now();
if(prev && prev.value===val && now>=prev.time && now-prev.time<900) {
    node.debug('DRY duplicate command ignored: '+key+' BMS_'+id);
    return null;
}
let reg, data, words;
if(key==='dry1_trigger_code'||key==='dry2_trigger_code') {
    if(!Number.isInteger(val)||val<0||val>14){node.warn('DRY invalid source code');return null;}
    const snapshot=global.get('dry_alpha4_static_BMS_'+id);
    if(!snapshot || !Number.isFinite(snapshot.time) || (Date.now()-snapshot.time)>120000 || snapshot.time>Date.now()+1000) {
        node.warn('DRY source write blocked: missing/recent STATIC snapshot BMS_'+id);return null;
    }
    const pair=(key==='dry1_trigger_code') ? snapshot.dry1 : snapshot.dry2;
    if(!Array.isArray(pair)||pair.length!==2||!pair.every(v=>Number.isInteger(v)&&v>=0&&v<=255)){
        node.warn('DRY source write blocked: invalid shared register snapshot');return null;
    }
    reg=key==='dry1_trigger_code'?0x14e4:0x14e6;
    data=Buffer.from(key==='dry1_trigger_code'?[pair[0],val]:[val,pair[1]]);
    words=1;
} else {
    reg={dry1_trigger_value:0x14f0,dry1_release_value:0x14f4,dry2_trigger_value:0x14f8,dry2_release_value:0x14fc}[key];
    if(reg===undefined)return null;
    if(!Number.isSafeInteger(val)||val < -100000||val >100000){node.warn('DRY raw threshold outside safety interval');return null;}
    data=Buffer.alloc(4);data.writeInt32BE(val,0);words=2;
}
const out=Buffer.from([id,0x10,(reg>>8)&255,reg&255,0,words,data.length,...data]);
let crc=0xffff;for(const x of out){crc^=x;for(let b=0;b<8;b++)crc=(crc&1)?((crc>>1)^0xa001):(crc>>1);}
msg.payload=Buffer.concat([out,Buffer.from([crc&255,(crc>>8)&255])]);
context.set(dedupKey,{value:val,time:now});
// Confirm only when a subsequent decoded STATIC sample matches the requested value.
// A queued command is NOT evidence of a successful Modbus write.
global.set(pendingKey,{bms:id,key:key,requested:val,register:reg,started:now,deadline:now+90000});
msg.dry_pending={bms:id,key,requested:val,register:reg};
node.warn('DRY write SENT, awaiting real STATIC readback: '+key+' BMS_'+id+' -> '+val);
return [msg, {payload:{bms:id,key:key,requested:val},topic:'DRY-READBACK-SCHEDULE'}];

const now=Date.now();
const fields=['dry1_trigger_code','dry2_trigger_code','dry1_trigger_value','dry1_release_value','dry2_trigger_value','dry2_release_value'];
for(let id=1;id<=15;id++) for(const key of fields){
    const token='dry_alpha6_pending_BMS_'+id+'_'+key;
    const p=global.get(token);
    if(p && Number.isFinite(p.deadline) && now>=p.deadline){
        node.warn('DRY STATIC READBACK TIMEOUT: BMS_'+id+' '+key+' requested '+p.requested+' (no matching STATIC frame within 90s)');
        global.set(token,null);
    }
}
return null;

// Readback only. Do not send if pending command was already verified or expired.
const p=msg.payload||{};
const id=Number(p.bms),key=String(p.key||'');
if(!Number.isInteger(id)||id<1||id>15||!/^dry[12]_(trigger_code|trigger_value|release_value)$/.test(key))return null;
if(global.get('bms_broadcasting')===true)return null;
const pending=global.get('dry_alpha6_pending_BMS_'+id+'_'+key);
if(!pending||pending.requested!==p.requested||Date.now()>=pending.deadline)return null;
// Exactly the historical Trame 1 request (FC16, register 0x161C, one zero word),
// but addressed explicitly to the BMS which was just written.
const bytes=Buffer.from([id,0x10,0x16,0x1c,0,1,2,0,0]);
let crc=0xffff;
for(const b of bytes){crc^=b;for(let j=0;j<8;j++)crc=(crc&1)?((crc>>>1)^0xa001):(crc>>>1);}
msg.payload=Buffer.concat([bytes,Buffer.from([crc&255,(crc>>>8)&255])]);
msg.topic='Trame-1-statiques';
msg.dry_targeted_readback=true;
node.warn('DRY STATIC targeted readback requested: BMS_'+id+' '+key);
return msg;

// Unified diagnostics - active polling: poll sent
// Transparent node: payload and business logic are not modified.

if (global.get("bms_broadcasting") === true) {
    return msg;
}

const now = Date.now();

function normalizeFrameType(topic) {
    const t = String(topic || "").toLowerCase();
    if (t.includes("trame-3") || t.includes("dynamic") || t.includes("live")) return "live";
    if (t.includes("trame-2") || t.includes("setup")) return "setup";
    if (t.includes("trame-1") || t.includes("static")) return "static";
    if (t.includes("alarm")) return "alarms";
    return t || "other";
}

let s = flow.get("diag_active_polling_stats") || {};
s.first_ts = s.first_ts || now;
s.polls_sent_30s = s.polls_sent_30s || 0;
s.responses_received_30s = s.responses_received_30s || 0;
s.valid_responses_30s = s.valid_responses_30s || 0;
s.response_time_sum_ms_30s = s.response_time_sum_ms_30s || 0;
s.response_time_count_30s = s.response_time_count_30s || 0;
s.max_response_time_ms_30s = s.max_response_time_ms_30s || 0;
s.pending = s.pending || {};
s.responding_seen = s.responding_seen || {};
s.polls_by_slave_30s = s.polls_by_slave_30s || {};
s.valid_by_slave_30s = s.valid_by_slave_30s || {};
s.timeouts_by_slave_30s = s.timeouts_by_slave_30s || {};
s.polls_by_frame_30s = s.polls_by_frame_30s || {};
s.valid_by_frame_30s = s.valid_by_frame_30s || {};
s.live_valid_by_slave_30s = s.live_valid_by_slave_30s || {};
s.last_valid_by_slave = s.last_valid_by_slave || {};
s.live_cycle_seen = s.live_cycle_seen || {};
s.complete_poll_cycles_30s = s.complete_poll_cycles_30s || 0;
s.cycle_time_sum_ms_30s = s.cycle_time_sum_ms_30s || 0;
s.cycle_time_count_30s = s.cycle_time_count_30s || 0;
s.max_cycle_time_ms_30s = s.max_cycle_time_ms_30s || 0;
s.seq = (Number(s.seq) || 0) + 1;

const buf = Buffer.isBuffer(msg.payload) ? msg.payload : null;
const slaveId = buf && buf.length > 0
    ? Number(buf[0])
    : Number(msg.bms_id || msg.bmsId || msg.bms_numero);
const rawFrameType = String(msg.topic || "unknown");
const frameType = normalizeFrameType(rawFrameType);
const txId = `${now}-${s.seq}`;

msg.diag_tx_id = txId;
msg.diag_poll_ts = now;
msg.diag_slave_id = Number.isFinite(slaveId) ? slaveId : null;
msg.diag_frame_type = frameType;
msg.diag_frame_topic = rawFrameType;

s.polls_sent_30s += 1;
s.last_poll_ts = now;
s.last_poll_slave_id = Number.isFinite(slaveId) ? slaveId : null;
s.last_poll_frame_type = frameType;
s.pending[txId] = {
    ts: now,
    slave_id: Number.isFinite(slaveId) ? slaveId : null,
    frame_type: frameType,
    frame_topic: rawFrameType
};

if (Number.isFinite(slaveId) && slaveId > 0) {
    const key = String(slaveId);
    s.polls_by_slave_30s[key] = (s.polls_by_slave_30s[key] || 0) + 1;
}
s.polls_by_frame_30s[frameType] = (s.polls_by_frame_30s[frameType] || 0) + 1;

flow.set("diag_active_polling_stats", s);
return msg;

// Derive live values that need more than a plain byte read.
// Runs directly after the "Trame 3" buffer parser, before every consumer.
const p = msg.payload;
if (!p || typeof p !== "object" || Array.isArray(p)) return msg;

const BALANCER_TEXT = { 0: "Off", 1: "Charging balancer", 2: "Discharging balancer" };
const BATTERY_TYPE_TEXT = { 0: "LFP", 1: "Li-ion", 2: "LTO" };

// Byte 172: 0 = off, 1 = charging balancer, 2 = discharging balancer.
// Earlier versions divided the byte by 100, so the binary sensor never turned on.
if (Number.isInteger(p.balancer_status_raw)) {
    const raw = p.balancer_status_raw;
    p.Balance_Action_B = raw !== 0 ? 1 : 0;      // keeps the existing entity id
    p.Balancer_status_N = raw;
    p.Balancer_status_text_S = BALANCER_TEXT[raw] || ("Unknown (" + raw + ")");
}
delete p.balancer_status_raw;

// Plain flags: publish strictly 0 / 1 so the binary sensors always match.
for (const key of ["Precharging_B", "Balancing_B", "Charger_plugged_B", "PCL_module_state_B"]) {
    if (p[key] !== undefined) p[key] = Number(p[key]) ? 1 : 0;
}

if (Number.isInteger(p.Battery_type_N)) {
    p.Battery_type_text_S = BATTERY_TYPE_TEXT[p.Battery_type_N] || ("Unknown (" + p.Battery_type_N + ")");
}

// Signed battery power (positive = charging, negative = discharging).
// "Puissance_Totale" from the frame is unsigned and stays unchanged.
const voltage = Number.isFinite(p.battery_voltage_mv_raw) && p.battery_voltage_mv_raw > 0
    ? p.battery_voltage_mv_raw / 1000
    : Number(p.Tension_Totale_volt_V);
const current = Number(p.Courant_total_A);
if (Number.isFinite(voltage) && voltage > 0 && Number.isFinite(current)) {
    p.Battery_power_W = Math.round(voltage * current * 10) / 10;
}
delete p.battery_voltage_mv_raw;

return msg;

// Derive live values that need more than a plain byte read.
// Runs directly after the "Trame 3" buffer parser, before every consumer.
const p = msg.payload;
if (!p || typeof p !== "object" || Array.isArray(p)) return msg;

const BALANCER_TEXT = { 0: "Off", 1: "Charging balancer", 2: "Discharging balancer" };
const BATTERY_TYPE_TEXT = { 0: "LFP", 1: "Li-ion", 2: "LTO" };

// Byte 172: 0 = off, 1 = charging balancer, 2 = discharging balancer.
// Earlier versions divided the byte by 100, so the binary sensor never turned on.
if (Number.isInteger(p.balancer_status_raw)) {
    const raw = p.balancer_status_raw;
    p.Balance_Action_B = raw !== 0 ? 1 : 0;      // keeps the existing entity id
    p.Balancer_status_N = raw;
    p.Balancer_status_text_S = BALANCER_TEXT[raw] || ("Unknown (" + raw + ")");
}
delete p.balancer_status_raw;

// Plain flags: publish strictly 0 / 1 so the binary sensors always match.
for (const key of ["Precharging_B", "Balancing_B", "Charger_plugged_B", "PCL_module_state_B"]) {
    if (p[key] !== undefined) p[key] = Number(p[key]) ? 1 : 0;
}

if (Number.isInteger(p.Battery_type_N)) {
    p.Battery_type_text_S = BATTERY_TYPE_TEXT[p.Battery_type_N] || ("Unknown (" + p.Battery_type_N + ")");
}

// Signed battery power (positive = charging, negative = discharging).
// "Puissance_Totale" from the frame is unsigned and stays unchanged.
const voltage = Number.isFinite(p.battery_voltage_mv_raw) && p.battery_voltage_mv_raw > 0
    ? p.battery_voltage_mv_raw / 1000
    : Number(p.Tension_Totale_volt_V);
const current = Number(p.Courant_total_A);
if (Number.isFinite(voltage) && voltage > 0 && Number.isFinite(current)) {
    p.Battery_power_W = Math.round(voltage * current * 10) / 10;
}
delete p.battery_voltage_mv_raw;

return msg;

// Build a Home Assistant dashboard "JK-BMS" with the card
// custom:bms-battery-cells-card-jkbms (HACS: Xander2980/bms-battery-cells-card-jkbms),
// one column per BMS. Only runs when the add-on option create_dashboard is on.
// The dashboard is owned by the add-on and rewritten on every start.
if (global.get("create_dashboard") !== true) {
    node.status({ fill: "grey", shape: "ring", text: "create_dashboard off" });
    return null;
}
const fsMod = global.get("fs");
const lang = String(global.get("ui.language") || "en");
const T = {
    de: { title: "JK-BMS", master: "Master-BMS", bms: "BMS" },
    en: { title: "JK-BMS", master: "Master BMS", bms: "BMS" },
    fr: { title: "JK-BMS", master: "BMS maître", bms: "BMS" }
}[lang] || { title: "JK-BMS", master: "Master BMS", bms: "BMS" };

// BMS ids actually seen in SETUP frames (kept by "Setup To MQTT"), else from the options
const now = Date.now();
const seen = global.get("premium.dashboard_bms_seen") || {};
let ids = Object.entries(seen)
    .filter(([, ts]) => Number.isFinite(Number(ts)) && now - Number(ts) < 10 * 60 * 1000)
    .map(([id]) => id);
if (!ids.length) {
    const count = Math.max(1, Number(global.get("nb_jkbms")) || 1);
    ids = global.get("bms_broadcasting") === true
        ? ["master", ...Array.from({ length: count - 1 }, (_, i) => String(i + 1))]
        : Array.from({ length: count }, (_, i) => String(i + 1));
}
ids.sort((a, b) => (a === "master" ? -1 : b === "master" ? 1 : Number(a) - Number(b)));

const card = (id) => ({
    type: "custom:bms-battery-cells-card-jkbms",
    jk_prefix: `bms_${id}`,
    title: id === "master" ? T.master : `${T.bms} ${id}`,
    show_detailed_view: true,
    show_status: true,
    balance_led: true,
    show_title_in_detail: true
});

const dashboard = {
    dashboard_meta: { url_path: "jk-bms", title: T.title, icon: "mdi:battery-charging-high", show_in_sidebar: true, require_admin: false },
    config: {
        title: T.title,
        views: [{
            title: T.title,
            path: "bms",
            type: "sections",
            max_columns: Math.min(4, ids.length),
            sections: ids.map(id => ({ type: "grid", cards: [card(id)] }))
        }]
    }
};

const file = "/config/dashboards/jk_bms_card.json";
try {
    fsMod.mkdirSync("/config/dashboards", { recursive: true });
    fsMod.writeFileSync(file, JSON.stringify(dashboard, null, 2));
} catch (e) {
    node.error("Could not write " + file + ": " + e.message);
    return null;
}
node.status({ fill: "green", shape: "dot", text: ids.length + " BMS: " + ids.join(", ") });
msg.payload = file;
return msg;
